#!/usr/bin/swift
import Foundation

// Simple approach: try to use Process to interact with simctl
// We'll try sending keyboard events via simctl

let processinfo = ProcessInfo.processInfo
let device = "34C0889B-D0E5-4FAD-86C6-14725980B267"

// Try to find the Open button and tap it
// The Open button appears to be at approximately (486, 863) based on the screenshot
print("Attempting to tap Open button...")

let task = Process()
task.executableURL = URL(fileURLWithPath: "/usr/bin/xcrun")
task.arguments = ["simctl", "spawn", device, "open", "bluesky://profile"]

do {
    try task.run()
    task.waitUntilExit()
    print("Spawn command completed")
} catch {
    print("Error: \(error)")
}

#import <Foundation/Foundation.h>
#import <Cocoa/Cocoa.h>
#import <ApplicationServices/ApplicationServices.h>

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        // Get the currently focused application
        AXUIElementRef appElement = AXUIElementCreateApplication(NSProcessInfo.processInfo.activeProcessIdentifier);

        // Try to find any window with "Open in" text
        CFArrayRef windowArray = nil;
        AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute, (CFTypeRef *)&windowArray);

        if (windowArray) {
            for (CFIndex i = 0; i < CFArrayGetCount(windowArray); i++) {
                AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windowArray, i);

                // Get window title
                CFTypeRef windowTitle = nil;
                AXUIElementCopyAttributeValue(window, kAXTitleAttribute, &windowTitle);

                // Look for buttons in the window
                CFArrayRef buttonArray = nil;
                AXUIElementCopyAttributeValue(window, kAXButtonsAttribute, (CFTypeRef *)&buttonArray);

                if (buttonArray) {
                    for (CFIndex j = 0; j < CFArrayGetCount(buttonArray); j++) {
                        AXUIElementRef button = (AXUIElementRef)CFArrayGetValueAtIndex(buttonArray, j);

                        // Get button title
                        CFTypeRef buttonTitle = nil;
                        AXUIElementCopyAttributeValue(button, kAXTitleAttribute, &buttonTitle);

                        // Check if this is the "Open" button
                        if (buttonTitle && CFEqual(buttonTitle, CFSTR("Open"))) {
                            NSLog(@"Found Open button, pressing it...");
                            AXUIElementPerformAction(button, kAXPressAction);
                            NSLog(@"Button pressed!");
                            return 0;
                        }

                        if (buttonTitle) CFRelease(buttonTitle);
                    }
                    CFRelease(buttonArray);
                }

                if (windowTitle) CFRelease(windowTitle);
            }
            CFRelease(windowArray);
        }

        CFRelease(appElement);
    }
    return 1;
}

#import <Foundation/Foundation.h>
#import <Cocoa/Cocoa.h>
#import <ApplicationServices/ApplicationServices.h>

void printElement(AXUIElementRef element, int depth) {
    CFStringRef role = nil;
    AXUIElementCopyAttributeValue(element, kAXRoleAttribute, (CFTypeRef *)&role);

    CFStringRef title = nil;
    AXUIElementCopyAttributeValue(element, kAXTitleAttribute, (CFTypeRef *)&title);

    if (role) {
        NSString *roleStr = (NSString *)role;
        NSString *titleStr = title ? (NSString *)title : @"";
        NSLog(@"%*sRole: %@, Title: %@", depth * 2, "", roleStr, titleStr);
    }

    if (role) CFRelease(role);
    if (title) CFRelease(title);
}

void searchForOpenButton(AXUIElementRef element, int depth) {
    CFStringRef role = nil;
    AXUIElementCopyAttributeValue(element, kAXRoleAttribute, (CFTypeRef *)&role);

    CFStringRef title = nil;
    AXUIElementCopyAttributeValue(element, kAXTitleAttribute, (CFTypeRef *)&title);

    // Check if this is the Open button
    if (title && CFEqual(title, CFSTR("Open"))) {
        NSLog(@"Found Open button!");
        AXUIElementPerformAction(element, kAXPressAction);
        NSLog(@"Pressed Open button");
    }

    if (role) CFRelease(role);
    if (title) CFRelease(title);

    // Search children
    CFArrayRef children = nil;
    AXUIElementCopyAttributeValue(element, kAXChildrenAttribute, (CFTypeRef *)&children);

    if (children && depth < 10) {
        for (CFIndex i = 0; i < CFArrayGetCount(children); i++) {
            AXUIElementRef child = (AXUIElementRef)CFArrayGetValueAtIndex(children, i);
            searchForOpenButton(child, depth + 1);
        }
        CFRelease(children);
    }
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSLog(@"Starting to search for Open button...");

        // Get all running applications
        NSArray *runningApps = [[NSWorkspace sharedWorkspace] runningApplications];
        for (NSRunningApplication *app in runningApps) {
            if ([[app localizedName] containsString:@"Simulator"] || [[app bundleIdentifier] containsString:@"com.apple.CoreSimulator"]) {
                NSLog(@"Found Simulator app: %@", [app localizedName]);

                AXUIElementRef appElement = AXUIElementCreateApplication([app processIdentifier]);

                // Get windows
                CFArrayRef windowArray = nil;
                AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute, (CFTypeRef *)&windowArray);

                if (windowArray) {
                    for (CFIndex i = 0; i < CFArrayGetCount(windowArray); i++) {
                        AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windowArray, i);

                        NSLog(@"Searching window %ld...", i);
                        searchForOpenButton(window, 0);
                    }
                    CFRelease(windowArray);
                }

                CFRelease(appElement);
            }
        }

        NSLog(@"Done");
    }
    return 0;
}

#import <Foundation/Foundation.h>
#import <Cocoa/Cocoa.h>
#import <ApplicationServices/ApplicationServices.h>

void searchElement(AXUIElementRef element, int depth, BOOL *found) {
    if (*found) return;

    CFStringRef title = nil;
    AXUIElementCopyAttributeValue(element, kAXTitleAttribute, (CFTypeRef *)&title);

    CFStringRef role = nil;
    AXUIElementCopyAttributeValue(element, kAXRoleAttribute, (CFTypeRef *)&role);

    if (title) {
        NSString *titleStr = (NSString *)title;
        if ([titleStr isEqualToString:@"Open"]) {
            NSLog(@"Found Open button! Role: %@", role ? (NSString *)role : @"unknown");
            AXUIElementPerformAction(element, kAXPressAction);
            NSLog(@"Pressed Open button");
            *found = YES;
            CFRelease(title);
            CFRelease(role);
            return;
        }
    }

    if (title) CFRelease(title);
    if (role) CFRelease(role);

    // Search children
    CFArrayRef children = nil;
    AXUIElementCopyAttributeValue(element, kAXChildrenAttribute, (CFTypeRef *)&children);

    if (children && depth < 20) {
        for (CFIndex i = 0; i < CFArrayGetCount(children); i++) {
            AXUIElementRef child = (AXUIElementRef)CFArrayGetValueAtIndex(children, i);
            searchElement(child, depth + 1, found);
            if (*found) break;
        }
        CFRelease(children);
    }
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSLog(@"Searching system for Open button...");

        BOOL found = NO;

        // Try to get the system-wide accessibility object
        AXUIElementRef systemElement = AXUIElementCreateSystemWide();

        CFArrayRef appArray = nil;
        AXUIElementCopyAttributeValue(systemElement, kAXApplicationsAttribute, (CFTypeRef *)&appArray);

        if (appArray) {
            NSLog(@"Found %ld applications", CFArrayGetCount(appArray));

            for (CFIndex i = 0; i < CFArrayGetCount(appArray) && !found; i++) {
                AXUIElementRef app = (AXUIElementRef)CFArrayGetValueAtIndex(appArray, i);

                CFStringRef name = nil;
                AXUIElementCopyAttributeValue(app, kAXTitleAttribute, (CFTypeRef *)&name);

                if (name) {
                    NSLog(@"Searching app: %@", (NSString *)name);
                    CFRelease(name);
                }

                // Search this app for the button
                searchElement(app, 0, &found);
            }

            CFRelease(appArray);
        }

        CFRelease(systemElement);

        if (found) {
            NSLog(@"Successfully pressed Open button");
        } else {
            NSLog(@"Open button not found");
        }
    }
    return 0;
}

