                        searchElement(window, 0, &found);
                    }
                    CFRelease(windowArray);
                }

                CFRelease(appElement);
            } @catch (NSException *e) {
                NSLog(@"Error accessing app: %@", e);
            }
        }

        if (found) {
            NSLog(@"Success!");
        } else {
            NSLog(@"Open button not found");
        }
    }
    return 0;
